import java.util.HashMap;
import java.util.Map;

Map returnMap = new HashMap();

if (managerAttributeValue == null) {
    log.warn("Manager Correlation - Split Pipeline: managerAttributeValue is null. Skipping manager correlation.");
    return null;
}

String managerAttrStr = managerAttributeValue.toString();

if (managerAttrStr.trim().isEmpty()) {
    log.warn("Manager Correlation - Split Pipeline: managerAttributeValue is empty. Skipping manager correlation.");
    return null;
}

if (!managerAttrStr.contains("|")) {
    log.error("Manager Correlation - Split Pipeline: managerAttributeValue does not contain the pipeline character '|'. Value: " + managerAttrStr);
    return null;
}

String[] parts = managerAttrStr.split("\\|", -1);

if (parts.length != 2) {
    log.error("Manager Correlation - Split Pipeline: Expected exactly 2 parts after splitting on '|', but got " + parts.length + ". Value: " + managerAttrStr);
    return null;
}

String identityAttrName = parts[0].trim();
String identityAttrValue = parts[1].trim();

if (identityAttrName.isEmpty()) {
    log.error("Manager Correlation - Split Pipeline: identityAttributeName (first part) is empty after splitting. Value: " + managerAttrStr);
    return null;
}

if (identityAttrValue.isEmpty()) {
    log.error("Manager Correlation - Split Pipeline: identityAttributeValue (second part) is empty after splitting. Value: " + managerAttrStr);
    return null;
}

log.debug("Manager Correlation - Split Pipeline: Resolved identityAttributeName='" + identityAttrName + "', identityAttributeValue='" + identityAttrValue + "'");

returnMap.put("identityAttributeName", identityAttrName);
returnMap.put("identityAttributeValue", identityAttrValue);

return returnMap;
